const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
const webpush = require('web-push');
const cron = require('node-cron');

const app = express();
app.use(cors());
app.use(express.json({ limit: '5mb' }));

const CONFIG_FILE = path.join(__dirname, 'push_data.json');

// 1. 配置 VAPID 签名（替换为你的密钥或环境变量）
const VAPID_PUBLIC_KEY = process.env.VAPID_PUBLIC_KEY || '<YOUR_VAPID_PUBLIC_KEY>';
const VAPID_PRIVATE_KEY = process.env.VAPID_PRIVATE_KEY || '<YOUR_VAPID_PRIVATE_KEY>';

webpush.setVapidDetails(
  'mailto:<YOUR_EMAIL>@example.com',
  VAPID_PUBLIC_KEY,
  VAPID_PRIVATE_KEY
);

// 2. 接收手机前端上报的订阅凭据与配置
app.post('/api/sync-push-config', (req, res) => {
  const { subscription, apiConfig, character, recentContext } = req.body;
  if (!subscription || !subscription.endpoint) {
    return res.status(400).json({ ok: false, error: '缺少有效推送凭据' });
  }

  const payload = {
    subscription,
    apiConfig,
    character,
    recentContext,
    updatedAt: Date.now()
  };
  fs.writeFileSync(CONFIG_FILE, JSON.stringify(payload, null, 2), 'utf-8');
  res.json({ ok: true, message: '配置同步成功' });
});

// 3. 测试通道连通性接口
app.get('/api/test-push', async (req, res) => {
  if (!fs.existsSync(CONFIG_FILE)) {
    return res.status(400).json({ error: '尚未绑定任何手机推送凭证' });
  }
  try {
    const data = JSON.parse(fs.readFileSync(CONFIG_FILE, 'utf-8'));
    const testPayload = JSON.stringify({
      title: data.character?.name || '伴侣消息',
      body: '收到测试推送，全链路配置成功！',
      url: '/'
    });
    await webpush.sendNotification(data.subscription, testPayload);
    res.json({ ok: true, message: '测试消息已成功投递至 APNs' });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message });
  }
});

// 4. 定时调度与大模型主动触发
async function checkAndTrigger() {
  if (!fs.existsSync(CONFIG_FILE)) return;
  // A. 免打扰过滤（如夜间 23:00~08:00 静默）
  // B. 动态冷却判断与概率留白（消除机械定时感）
  // C. 调用用户上报的 API Key 请求大模型生成口吻短句
  // D. 调用 webpush.sendNotification 推向苹果 APNs
}

cron.schedule('0 * * * *', () => {
  void checkAndTrigger();
});

// 5. 启动服务（必须显式绑定 0.0.0.0）
const PORT = process.env.PORT || 3456;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`PWA 推送微服务已在端口 ${PORT} 启动`);
});

# 宝塔站点反向代理配置片段
location ^~ / {
    proxy_pass http://127.0.0.1:3456;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header REMOTE-HOST $remote_addr;

    # 应对 iOS Safari 严苛的 OPTIONS 跨域预检死穴：
    # Nginx if 块会丢失外层 header，必须在 if 内完整注入响应头并返回 204
    if ($request_method = 'OPTIONS') {
        add_header 'Access-Control-Allow-Origin' '*' always;
        add_header 'Access-Control-Allow-Methods' 'GET, POST, OPTIONS' always;
        add_header 'Access-Control-Allow-Headers' 'DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range,Authorization' always;
        add_header 'Access-Control-Max-Age' 1728000 always;
        add_header 'Content-Type' 'text/plain; charset=utf-8' always;
        add_header 'Content-Length' 0 always;
        return 204;
    }
}
